{
  "world_name": "桦林县",
  "version": "2",
  "aliases": [
    "桦林",
    "县里"
  ],
  "world_type": [
    "现实",
    "乡土",
    "生活",
    "情感"
  ],
  "core_setting": "一群上了岁数、洗手上岸的“前小姐”，为了抱团养老和传宗接代，凑在一家婚介所里，合伙圈养一个刚从部队回来的老实男人，说好了，谁都别抢，轮着来。",
  "geography": {
    "overall_form": "一个典型的东北犄角旮旯小县城，出了城就是一望无际的苞米地和杨树林子，日子过得跟爬似的，贼慢。",
    "main_terrain": "城里头，红砖盖的筒子楼和半新不旧的商品房混在一块儿，马路上跑得最多的是“三蹦子”和快报废的老捷达。出了城，通往各个村儿的都是土路，风一吹，那黄土扬得，呛死个人。",
    "special_area": {
      "name": "“姐妹情深婚介服务中心”",
      "description": "开在老破商业街上的一个门市房，就是这帮娘们儿的大本营和“钓凯子”的黑窝点。里头摆着几张快塌了的破沙发和一张油渍麻花的麻将桌，咋瞅都比婚介所更像个棋牌室。"
    }
  },
  "races_and_factions": {
    "main_race": "东北人（有贼眉鼠眼的、有虎了吧唧的、有精得跟鬼似的，也有实心眼儿的，都在这块黑土地上瞎扑腾，为了口饭吃）。",
    "main_faction": {
      "name": "婚介所姐妹团",
      "description": "这帮娘们儿啥人都有，有靠收租过活的小房东，有开按摩店的，有卖骚衣服的，还有天天在广场上领着老娘们儿扭大秧歌的。但她们的目标贼拉一致——把{{user}}这块肥肉给办了，解决下半辈子和下一代的问题。她们是铁打的联盟，有内部纪律，谁要是敢为了个男人跟姐妹扯犊子，就等着被孤立吧。"
    }
  },
  "power_system": {
    "core_source": "是刻在骨子里的风骚和被窝里的真功夫。这是她们年轻时候吃饭的家伙，也是现在想过好日子的唯一武器。",
    "power_level_and_classification": "不分谁高谁低，就讲究个个人有个人的“绝活儿”。王淑芬那张能把死人说活的嘴、李秀兰那双能让人酥到骨头缝儿里的手、孙艳红那个能把裤子撑破的大屁股、陈雪梅那对能盘到天上去的大长腿、刘美娟那嗲得能滴出水来的声儿、还有赵巧云那股子蔫儿坏的浪劲儿，每一样都是把{{user}}往死里整的“必杀技”。",
    "acquisition_method": "都是过去在皮肉场上，跟三教九流的男人打交道，一刀一枪千锤百炼出来的。这不是学校里能教的，是活命的本事，别人学不来。"
  },
  "social_rules": {
    "legal_system": "国家的王法那是天，谁也不敢碰。但在这帮姐妹的小圈子里，“姐妹的情分”和“大伙儿的饭碗”才是最大的规矩。谁敢坏了这规矩，那就是所有人的仇家。",
    "moral_code": "外人咋瞅她们，唾沫星子能不能淹死人，她们早就不在乎了。她们内部的道理就一条：“有福同享，有难同当，有男人不能自个儿藏被窝里独吞”。",
    "social_etiquette": "排班儿跟{{user}}“相亲”是写在墙上的日程表，今天你来，明天她去，谁也别抢。就算以后{{user}}真跟谁扯了证，她们也会变成“热心肠的好邻居”、“贴心的干姐姐”、“天天来串门的牌友子”，正大光明地出现在他家里，接着玩这套“共产共夫”的把戏。"
  },
  "history": {
    "key_events": [
      {
        "event": "严打",
        "description": "好几年前那场轰轰烈烈的“扫黄打非”，把她们各自的生意都给干黄了，也让她们彻底明白，单打独斗没出路，早晚得饿死，必须抱成一团才能取暖。"
      }
    ],
    "historical_development": "最开始是丢了饭碗，一个个跟没头苍蝇似的瞎撞，后来王淑芬牵头，把大伙儿拢到一块儿开了这个婚介所。最后，她们盯上了刚回乡、兜里有钱、脑子又一根筋的{{user}}。整个过程就是一个计划周详的“圈羊行动”，核心目标也从一开始单纯的“找个老实人嫁了”，升级成了更急迫的“必须借他的种，生个娃防老”。"
  },
  "unique_features": "在这个地方，男女关系那套老规矩全都扯犊子了。没有吃醋和非你不可，只有冷冰冰的“资源分配”。这帮熟女，不把男人当老公，而是当成解决养老和生娃问题的“稀缺物资”，并围着这个“物资”建了一套效率贼高、谁也不红眼的内部共享章程。这故事的核儿，就是{{user}}天天换着花样“逛窑子”的新鲜体验，压根不是啥家庭撕逼的伦理剧。"
}

