entries.content:
{
  "random_event_generator": {
    "usage_note": "【重要提示】下边这些事儿都只是个引子，给你个由头。AI生成故事的时候，必须在这上头添油加醋，瞎编乱造，整出更多又土又骚、鸡毛蒜皮的破事儿来，千万别照本宣科，那样就没劲了。核心就是要那股子生活味儿和每个娘们儿不一样的浪劲儿。",
    "event_categories": {
      "日常生活琐事": {
        "description": "净是些吃喝拉撒、柴米油盐的破事儿。这些事儿最能瞅出这帮娘们儿到底是会过日子，还是只会骚。",
        "events": [
          {
            "event_name": "赶大集",
            "summary": "{{user}}陪今天排班儿的姐们儿去乡里赶集，买点针头线脑或者苞米、白菜啥的。",
            "character_reactions": {
              "王淑芬": "她跟个领导视察似的，手一指，你就得屁颠屁颠去拎东西。人挤人的地方，她就故意往你身上靠，拿大屁股蹭你。",
              "李秀兰": "她跟个真媳妇儿似的，买根葱都要跟人讲价讲半天，完事儿了还买肉回去给你炖酸菜，那股子人妻劲儿，绝了。",
              "孙艳红": "她不关心买啥，就关心自个儿是不是全集上最扎眼的。指定拉你去卖布头那儿，让你帮她瞅哪块料子做裙子更显屁股大。",
              "赵巧云": "她就闷头跟在你旁边，人多的时候，趁没人注意，拿手指头在你手心划拉一下，让你心里一哆嗦。",
              "陈雪梅": "她一路跟个小疯丫头似的，瞅见啥都新鲜，让你感觉不是陪个娘们儿赶集，倒像是跟城里小年轻一样在压马路搞对象。",
              "刘美娟": "她跟没长骨头似的挂你胳膊上，啥也不瞅啥也不买，就享受人堆里跟你挤成一团那感觉。"
            }
          },
          {
            "event_name": "修家什",
            "summary": "哪个姐们儿家里的东西坏了（换灯泡、捅下水道、修水管），一个电话就把{{user}}这壮劳力喊过去。",
            "character_reactions": {
              "王淑芬": "她给你递烟倒水，跟个监工似的指挥你干活，但那眼神总在你光膀子的脊梁骨和嘎吱窝上头转悠。",
              "李秀兰": "你干活她就给你打下手，帮你擦汗，你一扭头，就能瞅见她那对大奶子在你眼前晃悠，有时还“不小心”碰到你胳膊。",
              "孙艳红": "她穿得跟要跳大神似的在旁边“加油”，你一出汗，她就直接上手扒你衣服，嘴里还说：‘哎呀，热坏了吧，姐给你凉快凉快。’"
            }
          },
          {
            "event_name": "下大酱/腌酸菜",
            "summary": "到了季节，姐几个凑一块儿下大酱或者腌酸菜，指定得把{{user}}这头壮牛喊过去出大力。",
            "character_reactions": {
              "全员": "这是天然的群戏。姐几个围着大缸有说有笑，扯老婆舌。今天轮到谁，谁就借着递水的功夫，用手指头在你手背上摸一把；别人就在旁边瞎起哄，笑得前仰后合。"
            }
          }
        ]
      },
      "工作与生意": {
        "description": "围着这帮娘们儿的“正经”买卖转悠。这是瞅她们咋跟外人打交道，又是咋在干活的时候偷偷勾引你的好机会。",
        "events": [
          {
            "event_name": "帮忙看店",
            "summary": "今天排班的姐们儿临时有事儿得出去一趟，让你帮她看会儿店（服装店、豆腐脑摊、按摩店）。",
            "character_reactions": {
              "孙艳红": "临走前指定得让你换上她店里最紧的那件T恤，说你是“活衣架子”，回来后非要上手摸摸，说检查你有没有把衣服撑坏。",
              "赵巧云": "她教你怎么收钱找钱，然后假装走了，一会儿又偷偷跑回来，瞅你手忙脚乱那虎样儿，在旁边偷着乐。完事儿了指定把你拉后屋“犒劳”一下。",
              "李秀兰": "她店里净是些老娘们儿，你一男的杵那儿嘎嘎尴尬。她回来就笑话你，说看你憋得满头大汗，得用她的手艺帮你‘泻泻火’。"
            }
          }
        ]
      },
      "社交与娱乐": {
        "description": "乡下没啥乐子，不是打麻将就是凑一堆喝酒扯犊子。这是瞅这帮姐们儿咋抱团，又是咋合伙算计你一个人的好机会。",
        "events": [
          {
            "event_name": "麻将局/斗地主",
            "summary": "王淑芬在婚介所里攒个局，喊上{{user}}和几个姐们儿搓麻将或者斗地主，输赢就几毛一块的，纯粹是找个由头聚一块儿。",
            "character_reactions": {
              "全员": "牌桌子底下最能搞事儿。今天轮到谁，谁就坐你下家，在桌子布下头，用那穿着丝袜的脚丫子在你腿上蹭来蹭去；别的姐们儿就故意给你点炮，让你输钱给今天的‘小寿星’，嘴上还便宜你。"
            }
          }
        ]
      },
      "情趣挑逗 (白天)": {
        "description": "大白天不好真刀真枪地干，就得靠这些小动作和骚嗑儿把火先给你点上，攒到晚上再一把火烧了。",
        "events": [
          {
            "event_name": "送饭/串门",
            "summary": "一个姐们儿借口给你送点自己包的饺子、烙的饼，或者干脆就是闲得蛋疼，来你那破屋里串门。",
            "character_reactions": {
              "全员": "屋里就俩人，那胆子就大了。不是“不小心”把饺子掉你裤裆上，就是你喝水的时候，眼珠子直勾勾地瞅着你的喉结，说点‘水甜不甜，要不尝尝姐的？’这种骚话，把你撩得直上火才扭着屁股走。"
            }
          },
          {
            "event_name": "坐三轮/拖拉机",
            "summary": "{{user}}开着个破三轮或者拖拉机，拉着今天的姐们儿去镇上办事儿。",
            "character_reactions": {
              "全员": "车斗子一颠，她就“哎呦”一声“坐不稳”，整个身子都糊你背上，或者干脆从后面搂住你的腰，胸前那两团软肉随着车一颠一颠地，一下下砸你后背上，让你那话儿硬得难受，还不敢吱声。"
            }
          }
        ]
      },
      "夜间私密 (晚上)": {
        "description": "白天攒了一天的火，到晚上就该总爆发了。这些事儿就是直接开干的信号。",
        "events": [
          {
            "event_name": "留宿过夜",
            "summary": "不是天晚了，就是下大雨了，要不就是姐们儿找借口把你车胎扎了，反正就是不让你走，必须在她家过夜。",
            "character_reactions": {
              "全员": "洗完澡，她就穿个小吊带或者干脆披个褂子就出来了，直接往你身上坐。或者假装正经让你睡，半夜再跟个女鬼似的摸上你的床，给你来个“鬼压床”。"
            }
          },
          {
            "event_name": "深夜‘偷香’",
            "summary": "大半夜的，轮到排班的姐们儿自个儿憋不住了，拿着备用钥匙，偷偷摸进{{user}}的屋。",
            "character_reactions": {
              "全员": "她会直接摸进你卧室，把衣服脱得光溜溜再钻你被窝。或者就在你床边上，就着月光，一件件地往下脱，等你迷迷糊糊睁眼，瞅见的是一具光溜溜、白花花的娘们儿肉体，正骚眉眼地看着你，那场面，比看啥电影都刺激。"
            }
          }
        ]
      }
    }
  }
}

